function showMemberSessionLost(m){document.getElementById('memberChooser')?.remove();document.getElementById('auth')?.remove();toast('Impossible de reconnecter '+m.name+'. Réessayez depuis le choix des profils.') ;showMemberChooser()}
async function selectDeviceMember(m){if(m.role==='admin'){document.getElementById('memberChooser')?.remove();return ecran('admin',null,m.id)}return connectProfileById(m.id)}
async function connectProfileById(id){document.getElementById('memberChooser')?.remove();try{const result=await api('POST','/connexion/profil',{memberId:id,foyer:store.get(FOYER_KEY)||''});token=result.token;localStorage.setItem(TK,token);if(result.foyerCode)rememberFoyerCode(result.foyerCode);await charger();}catch(e){token=null;localStorage.removeItem(TK);toast(e.message||'Connexion impossible.');showMemberChooser()}}
