changeFoyer=()=>{token=null;localStorage.removeItem(TK);store.del(FOYER_KEY);showMemberChooser()};
regenerateFoyerCode=async()=>{try{const r=await api('POST','/admin/foyer-code/regenerer',{});rememberFoyerCode(r.foyerCode);await charger();toast('Nouveau code de foyer généré et enregistré sur cet appareil.')}catch(e){toast(e.message)}}
function quitAdmin(){if(!state.activeId||!isAdmin())return;token=null;localStorage.removeItem(TK);showMemberChooser()}
async function demarrer(){const p=new URLSearchParams(location.search),code=p.get('code');token=null;localStorage.removeItem(TK);if(code){try{const inf=await api('GET','/invitation/'+code);ecran('rejoindre',inf);}catch(e){ecran('connexion');const err=$('authErr');if(err)err.textContent=e.message;}return;}await showMemberChooser()}

// Bascule interne admin → membre : le jeton admin reste conservé uniquement en mémoire.
const baseSwitchUser=switchUser;
switchUser=async function(id){const me=state.members.find(x=>String(x.id)===String(state.activeId)),target=state.members.find(x=>String(x.id)===String(id));if(!me||!target||String(id)===String(state.activeId))return;if(me.role==='admin'){try{adminReturnToken=token;adminReturnProfile={id:me.id,name:me.name};const result=await api('POST','/admin/switch',{memberId:id});token=result.token;await charger();toast('Profil actif : '+target.name+' · retour Admin disponible.');}catch(e){adminReturnToken=null;toast(e.message||'Changement de profil impossible.');}}else if(target.role==='admin'){token=null;localStorage.removeItem(TK);ecran('admin',null,target.id);}else connectProfileById(id);};
returnToAdmin=async()=>{if(!adminReturnToken)return;token=adminReturnToken;await charger();adminReturnToken=null;toast('Retour au compte administrateur.');};
const oldCharger=charger;
let slideshowRouteHandled=false;charger=async function(){await oldCharger();const route=new URLSearchParams(location.search);if(!slideshowRouteHandled&&route.has('slideshow')&&state.members?.some(m=>String(m.id)===String(state.activeId))){slideshowRouteHandled=true;const wanted=route.get('slideshow');if(wanted)selectedAlbumId=wanted;state.view='photos';refreshShell();toast('Album prêt. Appuyez sur « Lancer en plein écran » pour démarrer le diaporama.')}const bar=document.querySelector('.top-actions');if(!bar)return;document.getElementById('returnAdmin')?.remove();if(adminReturnToken&&String(state.activeId)!==String(adminReturnProfile?.id)){const b=document.createElement('button');b.id='returnAdmin';b.className='btn soft';b.textContent='↩ Retour Admin';b.onclick=returnToAdmin;bar.append(b)}};
// Diaporama : API plein écran, tentative document parent same-origin et repli pseudo plein écran.
let fullSlideTimer=null,activityHandlers=null,slideStartedAt=0,fullSlideFirst=true,slideClosing=false,slidePreviousOverflow='',slideFallback=false,slideFullscreenDocument=document,slideDisplayDocument=document,slideWakeLock=null;
async function requestSlideWakeLock(){try{if('wakeLock'in navigator&&document.visibilityState==='visible'&&!slideClosing)slideWakeLock=await navigator.wakeLock.request('screen')}catch{}}
async function releaseSlideWakeLock(){try{if(slideWakeLock){const lock=slideWakeLock;slideWakeLock=null;await lock.release()}}catch{}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&document.getElementById('fullSlideshow'))requestSlideWakeLock()});

function closeFullSlideshow(){if(slideClosing)return;slideClosing=true;releaseSlideWakeLock();clearInterval(fullSlideTimer);fullSlideTimer=null;if(activityHandlers){for(const [target,ev,fn,opt] of activityHandlers)target.removeEventListener(ev,fn,opt);activityHandlers=null}const overlay=document.getElementById('fullSlideshow');if(overlay)overlay.remove();if(slideDisplayDocument!==document)slideDisplayDocument.getElementById('fullSlideshow')?.remove();document.body.style.overflow=slidePreviousOverflow||'';document.documentElement.classList.remove('slideshow-active');try{const doc=slideFullscreenDocument,exit=doc.exitFullscreen||doc.webkitExitFullscreen||doc.msExitFullscreen;if(exit&&(doc.fullscreenElement||doc.webkitFullscreenElement||doc.msFullscreenElement)){const result=exit.call(doc);result?.catch?.(()=>{});}}catch{}slideFullscreenDocument=document;slideDisplayDocument=document;token=null;adminReturnToken=null;adminReturnProfile=null;token=localStorage.getItem(TK)||null;document.getElementById('auth')?.remove();rememberKnownProfiles();showMemberChooser();setTimeout(()=>{slideClosing=false},0)}
function drawFullSlide(){const photos=(state.photos||[]).filter(p=>!selectedAlbumId||p.albumId===selectedAlbumId);if(!photos.length)return;if(fullSlideFirst)fullSlideFirst=false;else state.photoIndex=(state.photoIndex+1)%photos.length;state.photoIndex=((state.photoIndex%photos.length)+photos.length)%photos.length;const p=photos[state.photoIndex];const box=slideDisplayDocument.getElementById('fullSlideshow');if(!box)return;box.innerHTML=`<div class="full-slide-image" style="position:absolute;inset:0;display:grid;place-items:center;overflow:hidden;background:#101010">${p.image?'<img src="'+esc(p.image)+'" alt="" draggable="false" style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#101010">':'<span aria-hidden="true" style="font-size:min(34vw,240px)">'+esc(p.emoji||'📷')+'</span>'}<small class="full-slide-count" aria-hidden="true" style="position:absolute;right:5vw;bottom:6vh;font-size:16px;text-shadow:0 2px 8px #000">${state.photoIndex+1} / ${photos.length}</small></div>`}
function beginFullScreenSlideshow(){
  if(!(state.photos||[]).length||slideClosing)return;
  document.getElementById('fullSlideshow')?.remove();const box=document.createElement('div');box.id='fullSlideshow';box.setAttribute('role','dialog');box.setAttribute('aria-label','Diaporama plein écran');Object.assign(box.style,{position:'fixed',inset:'0',width:'100vw',height:'100vh',height:'100dvh',zIndex:'2147483647',background:'#000',color:'#fff'});document.body.append(box);
  slidePreviousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';document.documentElement.classList.add('slideshow-active');requestSlideWakeLock();slideClosing=false;slideFallback=false;slideStartedAt=Date.now();fullSlideFirst=true;slideFullscreenDocument=document;slideDisplayDocument=document;
  // L’appel initial reste synchrone avec le clic (requis par les navigateurs).
  const requestOn=doc=>{const el=doc.documentElement,fn=el.requestFullscreen||el.webkitRequestFullscreen||el.msRequestFullscreen;if(!fn)throw Error('Fullscreen indisponible');return fn.call(el)};
  const showFallbackHint=()=>{const msg=document.createElement('div');msg.className='full-slide-hint';msg.setAttribute('role','status');msg.textContent='Le plein écran natif est indisponible ; le diaporama reste affiché en plein écran simulé.';box.append(msg);setTimeout(()=>msg.remove(),6500)};
  let fullscreenPromise=null;try{fullscreenPromise=requestOn(document)}catch(error){fullscreenPromise=Promise.reject(error)}
  drawFullSlide();clearInterval(fullSlideTimer);fullSlideTimer=setInterval(drawFullSlide,Math.max(3,+state.photoInterval||5)*1000);
  let lastX=null,lastY=null;const real=ev=>{if(Date.now()-slideStartedAt<1500)return false;if(ev.type==='mousemove'){const x=ev.clientX,y=ev.clientY;if(lastX!==null&&Math.hypot(x-lastX,y-lastY)<4)return false;lastX=x;lastY=y;}return true};
  const targets=[window];try{if(window.self!==window.top&&window.top.document)targets.push(window.top)}catch{}activityHandlers=[];for(const target of targets)for(const ev of ['mousemove','mousedown','click','keydown','touchstart','wheel','pointermove','pointerdown']){const fn=e=>{if(real(e))closeFullSlideshow()};target.addEventListener(ev,fn,{passive:true});activityHandlers.push([target,ev,fn,{passive:true}])}
  const watchFs=doc=>{const fs=()=>{if(!(doc.fullscreenElement||doc.webkitFullscreenElement||doc.msFullscreenElement)&&!slideFallback)closeFullSlideshow()};['fullscreenchange','webkitfullscreenchange','MSFullscreenChange'].forEach(ev=>{doc.addEventListener(ev,fs);activityHandlers.push([doc,ev,fs,false])})};watchFs(document);
  Promise.resolve(fullscreenPromise).catch(async error=>{
    if(window.self!==window.top){try{const topDoc=window.top.document;if(topDoc?.documentElement){slideDisplayDocument=topDoc;topDoc.body.append(box);slideFullscreenDocument=topDoc;const p=requestOn(topDoc);watchFs(topDoc);await p;slideFallback=false;return}}catch(topError){console.log('[diaporama] Plein écran parent indisponible',topError?.message||topError)}}
    slideFallback=true;console.log('[diaporama] Repli pseudo plein écran',error?.message||error);showFallbackHint();
  });
}
const priorRender=render;
render=function(){priorRender();if(state.view==='home'||state.view==='progress')renderHomeRewards();if(state.view==='photos'){const head=document.getElementById('heroActions');if(head&&!head.querySelector('#startFullscreenSlide')){const b=document.createElement('button');b.id='startFullscreenSlide';b.type='button';b.className='btn primary';b.textContent=new URLSearchParams(location.search).has('slideshow')?'▶ Lancer en plein écran':'▶ Diaporama plein écran';b.addEventListener('click',beginFullScreenSlideshow);head.prepend(b)}}}
window.beginFullScreenSlideshow=beginFullScreenSlideshow;window.closeFullSlideshow=closeFullSlideshow;

function rewardProgress(r){const members=state.members||[],cost=Math.max(0,Number(r.cost)||0),selected=(r.members||[]).map(id=>members.find(m=>String(m.id)===String(id))).filter(Boolean),targets=selected.length?selected:members.map(m=>({...m,name:'Tout le foyer'}));if(!selected.length){const total=members.reduce((sum,m)=>sum+(Number(m.coins)||0),0);return [{name:'Tout le foyer',coins:total,remaining:cost-total,progress:cost?Math.min(100,total/cost*100):100}]}return targets.map(m=>{const coins=Number(m.coins)||0;return {name:m.name,coins,remaining:cost-coins,progress:cost?Math.min(100,coins/cost*100):100}})}
function rewardSignature(r,rows){return [String(r.id),String(r.title),String(r.cost),...(r.members||[]).map(String).sort(),...rows.map(x=>`${x.name}:${x.coins}`)].join('|')}
function renderHomeRewards(){const root=document.getElementById('content');if(!root)return;const section=document.createElement('section');section.className='panel home-rewards';section.style='margin-top:18px';const head=document.createElement('div');head.className='panel-head';head.innerHTML='<div><h2>Récompenses du foyer</h2><p>Des idées à partager contre des SuperCoins.</p></div>';const list=document.createElement('div');list.className='reward-list';const rewards=state.rewards||[];let congrats=[];
if(!rewards.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Aucune récompense pour le moment.';list.append(empty)}else rewards.forEach(r=>{const row=document.createElement('article');row.className='task-mini';row.style='padding:12px 0;border-top:1px solid var(--line);display:block';const top=document.createElement('div');top.style='display:flex;align-items:center;gap:9px;flex-wrap:wrap';const title=document.createElement('strong');title.textContent='🎁 '+r.title;title.style='flex:1';const assigned=(r.members||[]).map(id=>(state.members||[]).find(m=>String(m.id)===String(id))?.name).filter(Boolean);const targets=document.createElement('span');targets.className='tiny';targets.textContent=assigned.length?'Pour '+assigned.join(', '):'Pour tout le foyer';const cost=document.createElement('span');cost.className='coin';cost.textContent=Number(r.cost||0)+' SuperCoins ★';top.append(title,targets,cost);row.append(top);const progressRows=rewardProgress(r);progressRows.forEach(x=>{const area=document.createElement('div');area.style='margin-top:10px';const text=document.createElement('div');text.className='tiny';text.style='margin-bottom:5px';text.textContent=x.remaining<=0?`${x.name} : Objectif atteint (${Math.abs(x.remaining)} SuperCoins ${x.remaining<0?'au-delà':'restants'})`:`${x.name} : encore ${x.remaining} SuperCoins`;const bar=document.createElement('div');bar.className='progressbar';bar.setAttribute('aria-label',`${x.name}: ${Math.round(x.progress)} % de l’objectif`);const fill=document.createElement('span');fill.style.width=x.progress+'%';bar.append(fill);area.append(text,bar);row.append(area)});if(progressRows.some(x=>x.remaining<=0)){const sig=rewardSignature(r,progressRows);congrats.push({reward:r,rows:progressRows.filter(x=>x.remaining<=0),sig})}if(isAdmin()){const actions=document.createElement('div');actions.style='display:flex;justify-content:flex-end';const edit=document.createElement('button');edit.type='button';edit.className='link-btn';edit.textContent='Modifier';edit.onclick=()=>editReward(r.id);const del=document.createElement('button');del.type='button';del.className='link-btn';del.textContent='Supprimer';del.onclick=()=>deleteReward(r.id);actions.append(edit,del);row.append(actions)}list.append(row)});
section.append(head,list);if(isAdmin()){const form=document.createElement('form');form.id='rewardForm';form.className='reward-form';form.style='border-top:1px solid var(--line);padding-top:14px;margin-top:12px';form.onsubmit=saveReward;form.innerHTML='<input type="hidden" name="id"><div class="add-row"><input name="title" required maxlength="120" placeholder="Nouvelle récompense (ex. choisir le film)"><input type="number" name="cost" min="0" max="100000" step="1" value="0" aria-label="Coût en SuperCoins" style="max-width:145px"><button class="btn primary" type="submit">Ajouter</button></div><div class="tiny" style="margin-bottom:8px">Attribuer à (aucun choix = tout le foyer)</div><div class="member-pills">'+(state.members||[]).map(m=>'<label class="member-pill"><input type="checkbox" name="members" value="'+esc(m.id)+'"> '+esc(m.emoji)+' '+esc(m.name)+'</label>').join('')+'</div>';section.append(form)}else{const note=document.createElement('p');note.className='tiny';note.textContent='Consultation uniquement pour les membres.';section.append(note)}root.append(section);
if(state.view==='home')congrats.forEach(({reward,rows,sig})=>{const key='mm-reward-dismiss:'+encodeURIComponent(state.familyName||'')+':'+encodeURIComponent(sig);if(store.get(key))return;const banner=document.createElement('aside');banner.className='panel reward-congrats';banner.style='margin-top:14px;background:#fff5cc;border-color:#ecd689;position:relative';const names=rows.map(x=>x.name==='Tout le foyer'?'vous':x.name);const subject=names.length===1?names[0]:names.join(', ');banner.innerHTML='<button type="button" class="link-btn" aria-label="Fermer" style="position:absolute;right:10px;top:8px;font-size:20px" onclick="dismissRewardBanner(this)" data-dismiss-key="'+esc(key)+'">×</button><strong>🎉 Félicitations '+esc(subject)+' !</strong><p style="margin:8px 28px 0 0">Vous avez atteint/dépassé les '+Number(reward.cost||0)+' SuperCoins pour « '+esc(reward.title)+' » !</p>';root.prepend(banner)})}
dismissRewardBanner=button=>{const key=button?.dataset.dismissKey;if(key)store.set(key,'1');button.closest('.reward-congrats')?.remove()};
