let recipeOverlayScroll=0;
async function openFrenchRecipe(id,options={}){recipeOverlayScroll=window.scrollY;const wrap=document.createElement('div');wrap.id='recipeDetailOverlay';wrap.style='position:fixed;inset:0;z-index:120;background:var(--paper);overflow:auto;padding:20px';wrap.innerHTML='<div class="panel" style="max-width:850px;margin:20px auto"><p class="empty">Chargement de la recette…</p></div>';document.body.append(wrap);try{const favorite=options.favorite||null,saved=favorite?.data||{};let fetched={};try{fetched=await api('GET','/recettes/suggestions/'+encodeURIComponent(id))}catch(error){if(!favorite)throw error}const r={...saved,...fetched,title:fetched.title||favorite?.title||saved.title||'Recette',image:fetched.image||saved.image||'',source:fetched.source||saved.sourceUrl||'',sourceName:fetched.sourceName||saved.sourceName||(()=>{try{return new URL(fetched.source||saved.sourceUrl).hostname.replace(/^www\./,'')}catch{return favorite?'Recette favorite':'Recette familiale'}})(),area:fetched.area||saved.area||'',ingredients:Array.isArray(fetched.ingredients)&&fetched.ingredients.length?fetched.ingredients:(Array.isArray(saved.ingredients)?saved.ingredients:[]),instructions:saved.instructions||fetched.instructions||saved.description||'',description:saved.description||fetched.description||saved.instructions||''};wrap.innerHTML='';const panel=document.createElement('article');panel.className='panel';const back=document.createElement('button');back.className='btn soft';back.textContent=options.returnLabel||'← Retour aux recettes';back.onclick=()=>{wrap.remove();window.scrollTo(0,recipeOverlayScroll)};const art=document.createElement('div');art.style='min-height:210px;border-radius:18px;background:linear-gradient(135deg,#f2d79a,#e7a280);display:grid;place-items:center;font-size:100px;margin:20px 0;overflow:hidden';if(r.image){const img=document.createElement('img');img.src=r.image;img.alt=r.title;img.style='width:100%;max-height:360px;object-fit:cover';img.onerror=()=>{img.remove();art.textContent=r.emoji||'🍲'};art.append(img)}else art.textContent=r.emoji||'🍲';const title=document.createElement('h1');title.textContent=r.title;const intro=document.createElement('p');intro.className='modal-intro';intro.textContent=(r.sourceName||'Recette familiale')+(r.area?' · '+r.area:'');const h=document.createElement('h2');h.textContent='Ingrédients';const ul=document.createElement('ul');(r.ingredients||[]).forEach(x=>{const li=document.createElement('li');li.textContent=(x.measure?x.measure+' ':'')+(x.name||x);ul.append(li)});const sh=document.createElement('h2');sh.textContent='Préparation';const prep=document.createElement('p');prep.style='white-space:pre-line;line-height:1.8';prep.textContent=r.instructions||r.description||'La préparation détaillée n’est pas disponible.';panel.append(back,art,title,intro);if(r.description&&r.instructions&&r.description!==r.instructions){const desc=document.createElement('p');desc.className='modal-intro';desc.textContent=r.description;panel.append(desc)}panel.append(h,ul,sh,prep);if(r.source){try{const u=new URL(r.source);if(u.protocol==='https:'){const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener';a.className='btn primary';a.style='display:inline-block;margin-top:14px;text-decoration:none';a.textContent='Voir la recette sur le site ↗';panel.append(a)}}catch{}}wrap.append(panel)}catch(e){wrap.innerHTML='<div class="panel" style="max-width:700px;margin:20px auto"><p>'+esc(e.message)+'</p><button class="btn soft" onclick="document.getElementById(\'recipeDetailOverlay\').remove();window.scrollTo(0,recipeOverlayScroll)">← Retour aux recettes</button></div>'}}
loadMoreFrenchRecipes=async()=>{if(suggestionBusy)return;suggestionBusy=true;suggestionError='';const old=suggestionsWeb.slice();render();try{recipeSearchExclude=recipeExcludeParam();const params=new URLSearchParams({offset:String(recipeSearchOffset),seed:recipeSearchSeed,exclude:recipeSearchExclude,ingredients:recipeSearchProducts.join(',')});const result=await api('GET','/recettes/suggestions?'+params.toString()+'&_='+Date.now());const ids=new Set(old.map(x=>String(x.source||x.id)));const fresh=(result.recipes||[]).filter(x=>!ids.has(String(x.source||x.id)));if(fresh.length){suggestionsWeb=mergeRecipeResults(old,fresh);rememberRecipeResults(suggestionsWeb.slice(old.length))}recipeSearchOffset=Number(result.nextOffset)||recipeSearchOffset+fresh.length;recipesHasMore=!!result.hasMore;suggestionError=result.message||'';}catch(e){suggestionError=(e.message||'La recherche Internet a échoué.')+' Les recettes déjà affichées sont conservées.'}finally{suggestionBusy=false;render()}};


