// iOS: garder le champ du garde-manger au-dessus du clavier et retirer temporairement la barre fixe.
(() => {
  let focusedField=null, viewportTimer=0;
  const editable=el=>el?.matches?.('input:not([type=hidden]),select,textarea,[contenteditable="true"]');
  const syncKeyboard=()=>{
    const vv=window.visualViewport;
    const keyboardLikely=!!(focusedField&&document.activeElement===focusedField&&vv&&window.innerHeight-vv.height>120);
    document.body.classList.toggle('field-focused',!!(focusedField&&document.activeElement===focusedField));
    document.body.classList.toggle('keyboard-open',keyboardLikely);
    if(keyboardLikely&&focusedField?.isConnected){
      const r=focusedField.getBoundingClientRect(),vh=vv.height;
      if(r.bottom>vh-24||r.top<0)focusedField.scrollIntoView({block:'center',behavior:'smooth'});
    }
  };
  document.addEventListener('focusin',e=>{
    if(!editable(e.target))return;
    focusedField=e.target;
    window.setTimeout(()=>{focusedField?.scrollIntoView({block:'center',behavior:'smooth'});syncKeyboard()},250);
    window.setTimeout(syncKeyboard,650);
  });
  document.addEventListener('focusout',e=>{
    if(e.target!==focusedField)return;
    window.setTimeout(()=>{if(!editable(document.activeElement)){focusedField=null;document.body.classList.remove('keyboard-open','field-focused')}},250);
  });
  if(window.visualViewport){window.visualViewport.addEventListener('resize',()=>{clearTimeout(viewportTimer);viewportTimer=setTimeout(syncKeyboard,80)});window.visualViewport.addEventListener('scroll',()=>{clearTimeout(viewportTimer);viewportTimer=setTimeout(syncKeyboard,80)})}
})();
